def compute(vars):
    numerator = vars["v1"]
    denominator = vars["v2"]
    if denominator == 0:
        return None

    portion_percentage = (numerator / denominator) * 100
    result = round(portion_percentage)

    return {
        "value": result,
        "trace": {
            "numerator": numerator,
            "denominator": denominator,
            "portion_percentage": portion_percentage,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
